#!/usr/bin/env bash
#
# Borderline Cuba-hijacking cases added at the owner's direction (July 2026):
# the Tuller group (Eastern 486, October 29, 1972) and the Southern Airways
# Flight 49 hijackers (November 10-11, 1972). Both records state the violence
# plainly and frame the political nexus honestly — the Tullers' politics were
# self-described, and Southern 49 grew out of a police-brutality grievance
# but is generally treated as a ransom hijacking. All seven served long
# periods in Cuban custody.
#
# Idempotent: prisoner:add refuses duplicates (|| true keeps going).
#
# Run from the repo root:  bash database/data/add-tuller-southern49.sh

set -euo pipefail
cd "$(dirname "$0")/../.."

TULLER_CASE='{"charges":"Air piracy and murder — the October 29, 1972 seizure of Eastern Air Lines Flight 486 at Houston, in which ticket agent Stanley Hubbard was killed and a ramp employee wounded; preceded by a June 1972 Arlington, Virginia bank-robbery attempt that left two men dead","convicted":"Yes — convicted after surrendering in 1975; drew long prison terms"}'

php artisan prisoner:add '{"name":"Charles A. Tuller","first_name":"Charles","middle_name":"A.","last_name":"Tuller","description":"Charles A. Tuller was a former U.S. Commerce Department official from the Washington suburbs who reinvented himself as a self-styled revolutionary and led his teenage sons Bryce and Jonathan, with William White Graham, through a 1972 crime spree: a botched June bank robbery in Arlington, Virginia that left two men dead, and the October 29, 1972 hijacking of Eastern Air Lines Flight 486 from Houston to Havana, during which ticket agent Stanley Hubbard was killed. Cuba jailed the group on arrival rather than welcoming them; the Tullers surrendered to U.S. authorities in 1975 and were convicted, drawing long prison terms. The political character of the spree rested on Tuller'"'"'s own revolutionary self-description.","state":"Virginia","race":"White","gender":"Male","ideologies":["Self-described revolutionary"],"era":"1970s","released":true,"cases":['"$TULLER_CASE"']}' || true

php artisan prisoner:add '{"name":"Bryce Tuller","first_name":"Bryce","last_name":"Tuller","description":"Bryce Tuller was a teenage son of former Commerce Department official Charles A. Tuller and a participant in his father'"'"'s 1972 self-styled revolutionary crime spree: the botched June bank robbery in Arlington, Virginia that left two men dead, and the October 29, 1972 hijacking of Eastern Air Lines Flight 486 from Houston to Havana, during which ticket agent Stanley Hubbard was killed. Jailed in Cuba on arrival, he surrendered to U.S. authorities in 1975 with his father and brother and was convicted, drawing a long prison term.","state":"Virginia","race":"White","gender":"Male","ideologies":["Self-described revolutionary"],"era":"1970s","released":true,"cases":['"$TULLER_CASE"']}' || true

php artisan prisoner:add '{"name":"Jonathan Tuller","first_name":"Jonathan","last_name":"Tuller","description":"Jonathan Tuller was a teenage son of former Commerce Department official Charles A. Tuller and a participant in his father'"'"'s 1972 self-styled revolutionary crime spree: the botched June bank robbery in Arlington, Virginia that left two men dead, and the October 29, 1972 hijacking of Eastern Air Lines Flight 486 from Houston to Havana, during which ticket agent Stanley Hubbard was killed. Jailed in Cuba on arrival, he surrendered to U.S. authorities in 1975 with his father and brother and was convicted.","state":"Virginia","race":"White","gender":"Male","ideologies":["Self-described revolutionary"],"era":"1970s","released":true,"cases":['"$TULLER_CASE"']}' || true

php artisan prisoner:add '{"name":"William White Graham","first_name":"William","middle_name":"White","last_name":"Graham","description":"William White Graham was the teenage fourth member of the Tuller group'"'"'s 1972 self-styled revolutionary crime spree: the botched June bank robbery in Arlington, Virginia that left two men dead, and the October 29, 1972 hijacking of Eastern Air Lines Flight 486 from Houston to Havana, during which ticket agent Stanley Hubbard was killed. Jailed in Cuba on arrival, he returned to the United States after the Tullers and was prosecuted and imprisoned.","state":"Virginia","gender":"Male","ideologies":["Self-described revolutionary"],"era":"1970s","released":true,"cases":[{"charges":"Air piracy and murder — the October 29, 1972 seizure of Eastern Air Lines Flight 486 at Houston, in which ticket agent Stanley Hubbard was killed; preceded by the June 1972 Arlington, Virginia bank-robbery attempt that left two men dead","convicted":"Yes — returned to the U.S. after the Tullers and was prosecuted and imprisoned"}]}' || true

SOUTHERN49="the November 10-11, 1972 hijacking of Southern Airways Flight 49 from Birmingham — a 29-hour odyssey in which the hijackers collected a \$2 million ransom, wounded the copilot, and threatened to crash the plane into the Oak Ridge nuclear complex before landing in Havana"

php artisan prisoner:add '{"name":"Henry D. Jackson Jr.","first_name":"Henry","middle_name":"D.","last_name":"Jackson","description":"Henry D. Jackson Jr. was a Detroit man who, with Louis Cale (also known as Louis Moore) and Melvin Cale, carried out '"$SOUTHERN49"'. Jackson and Moore had a pending police-brutality suit against the Detroit police, the grievance behind the act, though it is generally treated as a ransom hijacking. Cuban courts sentenced Jackson to 20 years, and he served about eight years in Cuban prisons before being returned to the United States in 1980, where he faced federal air-piracy prosecution and a further prison term.","state":"Michigan","race":"Black","gender":"Male","era":"1970s","released":true,"cases":[{"charges":"Air piracy — Southern Airways Flight 49 (November 10-11, 1972); sentenced to 20 years by a Cuban court on arrival","arrest_date":"1972-11-11","convicted":"Yes — about eight years in Cuban prisons, then U.S. federal prosecution on return in 1980","imprisoned_for_days":2900}]}' || true

php artisan prisoner:add '{"name":"Louis Cale","first_name":"Louis","last_name":"Cale","aka":"Louis Moore","description":"Louis Cale, also known as Louis Moore, was a Detroit man who, with Henry D. Jackson Jr. and his half-brother Melvin Cale, carried out '"$SOUTHERN49"'. Moore and Jackson had a pending police-brutality suit against the Detroit police, the grievance behind the act, though it is generally treated as a ransom hijacking. Cuban courts sentenced him to 20 years, and he served about eight years in Cuban prisons before being returned to the United States in 1980, where he faced federal air-piracy prosecution and a further prison term.","state":"Michigan","race":"Black","gender":"Male","era":"1970s","released":true,"cases":[{"charges":"Air piracy — Southern Airways Flight 49 (November 10-11, 1972); sentenced to 20 years by a Cuban court on arrival","arrest_date":"1972-11-11","convicted":"Yes — about eight years in Cuban prisons, then U.S. federal prosecution on return in 1980","imprisoned_for_days":2900}]}' || true

